## 5. Byte-Identity Acceptance Test

The test proves that `detect_consensus_illusion()` is a pure function: same inputs → same output bytes, always, on any machine, any time.

```rust
#[cfg(test)]
mod acceptance_tests {
    use super::*;

    /// Reference vectors: precomputed inputs and expected outputs.
    /// These are immutable constants committed to the chain genesis.
    const TEST_VECTOR_TRUE_CONSENSUS: &str = include_str!("vectors/true_consensus.json");
    const TEST_VECTOR_CORRELATED: &str = include_str!("vectors/correlated.json");
    const TEST_VECTOR_INSUFFICIENT: &str = include_str!("vectors/insufficient.json");

    #[test]
    fn test_byte_identity_true_consensus() {
        let round: ConsensusRound =
            serde_json::from_str(TEST_VECTOR_TRUE_CONSENSUS).unwrap();

        // Run detection 100 times
        let mut results = HashSet::new();
        for _ in 0..100 {
            let v = detect_consensus_illusion(&round);
            let bytes = bincode::serialize(&v).unwrap();
            results.insert(bytes);
        }

        // Exactly ONE distinct byte sequence across all runs
        assert_eq!(results.len(), 1,
            "Non-deterministic: {} distinct outputs", results.len());

        // Matches expected value
        let expected_bytes = bincode::serialize(&ConsensusVerdict::TrueConsensus).unwrap();
        assert_eq!(results.iter().next().unwrap(), &expected_bytes);
    }

    #[test]
    fn test_byte_identity_correlated_hallucination() {
        let round: ConsensusRound =
            serde_json::from_str(TEST_VECTOR_CORRELATED).unwrap();

        let mut results = HashSet::new();
        for _ in 0..100 {
            let v = detect_consensus_illusion(&round);
            let bytes = bincode::serialize(&v).unwrap();
            results.insert(bytes);
        }

        assert_eq!(results.len(), 1);
        let expected_bytes =
            bincode::serialize(&ConsensusVerdict::CorrelatedHallucination).unwrap();
        assert_eq!(results.iter().next().unwrap(), &expected_bytes);
    }

    #[test]
    fn test_state_transition_is_deterministic() {
        let prev_state = load_test_lattice_state();
        let round: ConsensusRound =
            serde_json::from_str(TEST_VECTOR_TRUE_CONSENSUS).unwrap();

        let next_a = apply_state_transition(&prev_state, &round);
        let next_b = apply_state_transition(&prev_state, &round);

        // Byte-for-byte identity of entire state
        assert_eq!(
            sha3_256(&bincode::serialize(&next_a).unwrap()),
            sha3_256(&bincode::serialize(&next_b).unwrap()),
        );

        // Exactly one entry changed
        let diff = diff_states(&prev_state, &next_a);
        assert_eq!(diff.len(), 1);
        assert_eq!(diff[0].key, round.target_invariant.canonical_hash);
    }

    #[test]
    fn test_serialization_is_canonical() {
        // Two structurally-equal rounds built differently → same bytes
        let round_a = build_round_ordering_a();
        let round_b = build_round_ordering_b(); // same content, different insertion order

        let canon_a = canonical_serialize(&round_a);
        let canon_b = canonical_serialize(&round_b);

        assert_eq!(canon_a, canon_b,
            "Serialization is order-dependent — violates byte-identity");
    }

    #[test]
    fn test_catches_specific_correlation_attack() {
        // Simulate: 10 verifiers all trained on same buggy dataset.
        // They all "confirm" a false invariant AND all fail to reject decoys.
        let round = build_correlated_attack_scenario();

        let verdict = detect_consensus_illusion(&round);
        assert_eq!(verdict, ConsensusVerdict::CorrelatedHallucination);

        // Specifically: caught by Gate 2 (decoy rejection)
        assert!(compute_decoy_rate(&round) < 0.90);
    }

    #[test]
    fn test_passes_genuine_independent_consensus() {
        // Simulate: 10 verifiers with diverse architectures, different seeds,
        // different proof strategies, all correctly rejecting decoys.
        let round = build_genuine_consensus_scenario();

        let verdict = detect_consensus_illusion(&round);
        assert_eq!(verdict, ConsensusVerdict::TrueConsensus);

        // Verify all gates pass individually
        assert!(unanimous_primary(&round));
        assert!(compute_decoy_rate(&round) >= 0.90);
        assert!(min_normalized_path_distance(&round) >= 0.15);
    }
}
```

